def _run_reference_integrity() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_REFERENCE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = validate_references(
            payload.get("datasets"),
            payload.get("rules"),
        )
    except InvalidReferenceInputError as exc:
        return _emit_error("INVALID_REFERENCE_INPUT", str(exc))
    except InvalidReferenceRuleError as exc:
        return _emit_error("INVALID_REFERENCE_RULE", str(exc))
    except UnknownReferenceDatasetError as exc:
        return _emit_error("UNKNOWN_REFERENCE_DATASET", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_quality_gates() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_INPUT", "input payload must be a JSON object"
        )
    for key in ("records", "rules", "gates"):
        if key not in payload:
            return _emit_error(
                "INVALID_INPUT", f"payload is missing {key!r}"
            )

    try:
        result = evaluate_quality_gates(
            payload.get("dataset"),
            payload["records"],
            payload["rules"],
            payload["gates"],
        )
    except InvalidRuleError as exc:
        return _emit_error("INVALID_RULE", str(exc))
    except InvalidInputError as exc:
        return _emit_error("INVALID_INPUT", str(exc))
    except InvalidQualityGateRuleError as exc:
        return _emit_error("INVALID_QUALITY_GATE_RULE", str(exc))
    except UnknownQualityGateSourceError as exc:
        return _emit_error("UNKNOWN_QUALITY_GATE_SOURCE", str(exc))
    except DataQualityError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dq",
        description="Data quality rule validation and lineage tracing.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    validate_parser = subparsers.add_parser(
        "validate",
        help="validate records from a UTF-8 JSON object on standard input",
    )
    validate_parser.set_defaults(handler=_run_validate)

    lineage_parser = subparsers.add_parser(
        "lineage",
        help="trace upstream/downstream lineage from a UTF-8 JSON object "
        "on standard input",
    )
    lineage_parser.set_defaults(handler=_run_lineage)

    field_lineage_parser = subparsers.add_parser(
        "field-lineage",
        help="trace upstream/downstream field-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    field_lineage_parser.set_defaults(handler=_run_field_lineage)

    lineage_paths_parser = subparsers.add_parser(
        "lineage-paths",
        help="explain ordered upstream/downstream lineage paths from a "
        "UTF-8 JSON object on standard input",
    )
    lineage_paths_parser.set_defaults(handler=_run_lineage_paths)

    field_lineage_paths_parser = subparsers.add_parser(
        "field-lineage-paths",
        help="explain ordered upstream/downstream field-level lineage paths "
        "from a UTF-8 JSON object on standard input",
    )
    field_lineage_paths_parser.set_defaults(handler=_run_field_lineage_paths)

    correlate_parser = subparsers.add_parser(
        "correlate",
        help="group violation results into cross-rule correlation events "
        "from a UTF-8 JSON object on standard input",
    )
    correlate_parser.set_defaults(handler=_run_correlate)

    correlate_links_parser = subparsers.add_parser(
        "correlate-links",
        help="group violation results across linked samples into "
        "cross-dataset correlation events from a UTF-8 JSON object on "
        "standard input",
    )
    correlate_links_parser.set_defaults(handler=_run_correlate_links)

    violation_origins_parser = subparsers.add_parser(
        "violation-origins",
        help="analyze upstream/self origin and downstream impact evidence "
        "of violated targets from a UTF-8 JSON object on standard input",
    )
    violation_origins_parser.set_defaults(handler=_run_violation_origins)

    field_impact_parser = subparsers.add_parser(
        "field-impact",
        help="analyze downstream field-level quality impact from a UTF-8 "
        "JSON object on standard input",
    )
    field_impact_parser.set_defaults(handler=_run_field_impact)

    query_results_parser = subparsers.add_parser(
        "query-results",
        help="filter complete composite rule results by rule id, severity "
        "or record locator from a UTF-8 JSON object on standard input",
    )
    query_results_parser.set_defaults(handler=_run_query_results)

    snapshot_diff_parser = subparsers.add_parser(
        "snapshot-diff",
        help="compare violated results of two quality check snapshots over "
        "the shared lineage graph from a UTF-8 JSON object on standard "
        "input",
    )
    snapshot_diff_parser.set_defaults(handler=_run_snapshot_diff)

    reference_integrity_parser = subparsers.add_parser(
        "reference-integrity",
        help="validate cross-dataset reference integrity rules from a "
        "UTF-8 JSON object on standard input",
    )
    reference_integrity_parser.set_defaults(handler=_run_reference_integrity)

    quality_gates_parser = subparsers.add_parser(
        "quality-gates",
        help="aggregate single-field rule failure ratios into dataset-level "
        "quality gates from a UTF-8 JSON object on standard input",
    )
    quality_gates_parser.set_defaults(handler=_run_quality_gates)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.handler()


if __name__ == "__main__":
    sys.exit(main())

"""Unit tests for dataset-level quality gate aggregation."""

import unittest

from data_quality import InvalidInputError, InvalidRuleError
from data_quality.quality_gates import (
    InvalidQualityGateRuleError,
    UnknownQualityGateSourceError,
    evaluate_quality_gates,
)


def rule(rule_id="age-range", field="age", minimum=0, maximum=120):
    return {
        "id": rule_id,
        "type": "range",
        "options": {"field": field, "min": minimum, "max": maximum},
    }


def gate(
    rule_id="g1",
    source_rule_id="age-range",
    max_failed_ratio=0.5,
    severity="error",
):
    return {
        "rule_id": rule_id,
        "source_rule_id": source_rule_id,
        "max_failed_ratio": max_failed_ratio,
        "severity": severity,
    }


RECORDS = [
    {"id": "r1", "age": 200},
    {"id": "r2", "age": 50},
    {"id": "r3", "age": 7},
]


class EvaluateQualityGatesSuccessTest(unittest.TestCase):
    def test_report_shape(self):
        result = evaluate_quality_gates(
            "people", RECORDS, [rule()], [gate(max_failed_ratio=0.2)]
        )
        self.assertEqual(
            result,
            {
                "dataset": "people",
                "results": [
                    {
                        "rule_id": "g1",
                        "source_rule_id": "age-range",
                        "status": "FAILED",
                        "failed_count": 1,
                        "record_count": 3,
                        "ratio": 1 / 3,
                        "samples": [
                            {
                                "record_index": 0,
                                "record_id": "r1",
                                "field": "age",
                                "value": 200,
                                "message": "is out of the allowed range",
                            }
                        ],
                    }
                ],
            },
        )

    def test_ratio_equal_to_threshold_is_passed(self):
        # 1 of 2 records fails: ratio 0.5, threshold 0.5 -> PASSED.
        records = [{"id": "r1", "age": 200}, {"id": "r2", "age": 10}]
        passed = evaluate_quality_gates(
            "d", records, [rule()], [gate(max_failed_ratio=0.5)]
        )
        self.assertEqual(passed["results"][0]["status"], "PASSED")
        self.assertEqual(passed["results"][0]["ratio"], 0.5)

        just_above = evaluate_quality_gates(
            "d", records, [rule()], [gate(max_failed_ratio=0.49)]
        )
        self.assertEqual(just_above["results"][0]["status"], "FAILED")

    def test_zero_ratio_passes(self):
        result = evaluate_quality_gates(
            "d", [{"id": "r1", "age": 10}], [rule()], [gate()]
        )
        entry = result["results"][0]
        self.assertEqual(entry["status"], "PASSED")
        self.assertEqual(entry["failed_count"], 0)
        self.assertEqual(entry["ratio"], 0)
        self.assertEqual(entry["samples"], [])

    def test_threshold_one_passes_even_when_all_fail(self):
        records = [{"age": 999}, {"age": 999}]
        result = evaluate_quality_gates(
            "d", records, [rule()], [gate(max_failed_ratio=1)]
        )
        self.assertEqual(result["results"][0]["status"], "PASSED")
        self.assertEqual(result["results"][0]["ratio"], 1.0)

    def test_threshold_zero_any_failure_fails(self):
        records = [{"age": 1}, {"age": 999}]
        result = evaluate_quality_gates(
            "d", records, [rule()], [gate(max_failed_ratio=0)]
        )
        self.assertEqual(result["results"][0]["status"], "FAILED")

    def test_empty_dataset_is_skipped(self):
        result = evaluate_quality_gates("empty", [], [rule()], [gate()])
        entry = result["results"][0]
        self.assertEqual(entry["status"], "SKIPPED_EMPTY_DATASET")
        self.assertEqual(entry["record_count"], 0)
        self.assertEqual(entry["failed_count"], 0)
        self.assertIsNone(entry["ratio"])
        self.assertEqual(entry["samples"], [])

    def test_gates_aggregated_in_order_with_different_sources(self):
        rules = [
            {"id": "name-req", "type": "required", "options": {"field": "name"}},
            rule(),
        ]
        records = [
            {"id": "r1", "age": 10},
            {"id": "r2", "age": 200},
        ]
        gates = [
            gate("g-age", "age-range", 0.0, "error"),
            gate("g-name", "name-req", 1.0, "info"),
        ]
        result = evaluate_quality_gates("d", records, rules, gates)
        self.assertEqual(
            [entry["rule_id"] for entry in result["results"]],
            ["g-age", "g-name"],
        )
        self.assertEqual(result["results"][0]["failed_count"], 1)
        self.assertEqual(result["results"][1]["failed_count"], 2)

    def test_samples_follow_record_order_and_keep_fields(self):
        records = [
            {"age": 999},
            {"id": "b", "age": 10},
            {"id": "c", "age": 999},
        ]
        result = evaluate_quality_gates(
            "d", records, [rule()], [gate(max_failed_ratio=0.1)]
        )
        samples = result["results"][0]["samples"]
        self.assertEqual([sample["record_index"] for sample in samples], [0, 2])
        self.assertEqual(
            [sample["record_id"] for sample in samples], [None, "c"]
        )
        self.assertTrue(
            all(sample["field"] == "age" for sample in samples)
        )
        self.assertTrue(
            all(sample["value"] == 999 for sample in samples)
        )
        self.assertEqual(
            {
                "record_index",
                "record_id",
                "field",
                "value",
                "message",
            },
            set(samples[0]),
        )

    def test_severity_is_echoed_nowhere_but_accepted(self):
        for severity in ("error", "warning", "info"):
            result = evaluate_quality_gates(
                "d", RECORDS, [rule()], [gate(severity=severity)]
            )
            self.assertEqual(
                set(result["results"][0]),
                {
                    "rule_id",
                    "source_rule_id",
                    "status",
                    "failed_count",
                    "record_count",
                    "ratio",
                    "samples",
                },
            )

    def test_dataset_may_be_none(self):
        result = evaluate_quality_gates(None, RECORDS, [rule()], [gate()])
        self.assertIsNone(result["dataset"])

    def test_unique_rule_violations_are_used_as_defined(self):
        rules = [
            {"id": "code-uq", "type": "unique", "options": {"field": "code"}}
        ]
        records = [
            {"id": "r1", "code": "x"},
            {"id": "r2", "code": "x"},
            {"id": "r3", "code": "x"},
        ]
        result = evaluate_quality_gates(
            "d", records, rules, [gate(source_rule_id="code-uq")]
        )
        entry = result["results"][0]
        # Only the later duplicates are violations under the unique rule.
        self.assertEqual(entry["failed_count"], 2)
        self.assertEqual(
            [sample["record_index"] for sample in entry["samples"]], [1, 2]
        )


class EvaluateQualityGatesInputErrorTest(unittest.TestCase):
