class CliQualityGatesExemptionTest(unittest.TestCase):
    def assert_error(self, proc, code):
        self.assertEqual(proc.returncode, 2, proc.stdout)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertEqual(body["error"]["code"], code)
        self.assertIn("message", body["error"])

    def test_omitted_exemptions_keep_baseline_shape(self):
        records = [{"id": "r1", "age": 200}, {"id": "r2", "age": 5}]
        proc = run_json(payload(records, [gate(max_failed_ratio=0.1)]))
        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        entry = body["results"][0]
        self.assertEqual(entry["failed_count"], 1)
        self.assertNotIn("waived_count", entry)
        self.assertNotIn("waived_samples", entry)

    def test_waived_violation_flips_failed_to_passed(self):
        records = [{"id": "r1", "age": 200}, {"id": "r2", "age": 5}]
        proc = run_json(
            payload(
                records,
                [gate(max_failed_ratio=0.1)],
                exemptions=[exemption()],
            )
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        entry = body["results"][0]
        self.assertEqual(entry["status"], "PASSED")
        self.assertEqual(entry["failed_count"], 0)
        self.assertEqual(entry["ratio"], 0.0)
        self.assertEqual(entry["samples"], [])
        self.assertEqual(entry["waived_count"], 1)
        self.assertEqual(
            entry["waived_samples"][0],
            {
                "record_index": 0,
                "record_id": "r1",
                "field": "age",
                "value": 200,
                "message": "is out of the allowed range",
                "exemption_id": "e1",
                "reason": "known legacy value",
            },
        )

    def test_bad_exemption_is_invalid_exemption_input(self):
        records = [{"id": "r1", "age": 200}, {"id": "r2", "age": 5}]
        bad = exemption()
        bad["record_index"] = True
        self.assert_error(
            run_json(
                payload(
                    records,
                    [gate(max_failed_ratio=0.1)],
                    exemptions=[bad],
                )
            ),
            "INVALID_EXEMPTION_INPUT",
        )

    def test_unmatched_exemption_is_invalid_exemption_input(self):
        records = [{"id": "r1", "age": 200}, {"id": "r2", "age": 5}]
        self.assert_error(
           _run := run_json(
                payload(
                    records,
                    [gate(max_failed_ratio=0.1)],
                    exemptions=[exemption(record_index=1, record_id="r2")],
                )
            ),
            "INVALID_EXEMPTION_INPUT",
        )

    def test_duplicate_conflict_is_invalid_exemption_input(self):
        records = [{"id": "r1", "age": 200}, {"id": "r2", "age": 5}]
        self.assert_error(
            run_json(
                payload(
                    records,
                    [gate(max_failed_ratio=0.1)],
                    exemptions=[
                        exemption("e1"),
                        exemption("e2", reason="other"),
                    ],
                )
            ),
            "INVALID_EXEMPTION_INPUT",
        )


if __name__ == "__main__":
    unittest.main()

input.new_string:
从标准输入读取一个 UTF-8 JSON 对象，必填 `records`、`rules`、`gates`，可选 `dataset` 与 `exemptions`；规则、门槛与豁免契约与 `evaluate_quality_gates` 的 Python 输入完全相同：

```bash
dq quality-gates < gates.json
```

```json
{
  "dataset": "people",
  "records": [{"id": "r1", "age": 200}, {"id": "r2", "age": 5}],
  "rules": [
    {"id": "age-range", "type": "range", "options": {"field": "age", "min": 0, "max": 120}}
  ],
  "gates": [
    {"rule_id": "age-gate", "source_rule_id": "age-range", "max_failed_ratio": 0.1, "severity": "error"}
  ],
  "exemptions": [
    {"exemption_id": "e-legacy", "rule_id": "age-range", "record_index": 0, "record_id": "r1", "field": "age", "reason": "历史数据已知问题"}
  ]
}
```

标准输出为与 Python 入口完全相同的一行 JSON 报告（`dataset`、`results`）；省略 `exemptions` 或传空列表时报告与基线相同，否则每个门槛结果另含 `waived_count` 与 `waived_samples`。合法执行即使出现 `FAILED` 或 `SKIPPED_EMPTY_DATASET` 也退出 0；输入有误时退出码为 2，标准输出仅含顶层 `error` 对象（只有 `code`、`message` 两个键），错误码依次为：

- `INVALID_JSON`：输入不是合法 UTF-8 或无法解析为 JSON。
- `INVALID_INPUT`：载荷不是 JSON 对象、缺少 `records`/`rules`/`gates`，或 `records` 结构错误。
- `INVALID_RULE`：单字段规则定义非法。
- `INVALID_QUALITY_GATE_RULE`：门槛结构非法、`rule_id` 重复、`severity` 非法，或 `max_failed_ratio` 不是 0–1 的 JSON 数字。
- `UNKNOWN_QUALITY_GATE_SOURCE`：门槛的 `source_rule_id` 未在 `rules` 中声明。
- `INVALID_EXEMPTION_INPUT`：豁免无效、重复、冲突或未匹配到异常。

